const addDays=(day,n)=>{const d=dayOf(day);d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
const monday=day=>addDays(day,-(dayOf(day).getUTCDay()+6)%7);
const nextMonth=m=>{let[y,mo]=m.split('-').map(Number);return mo===12?`${y+1}-01`:`${y}-${n2(mo+1)}`};
const prevMonth=m=>{let[y,mo]=m.split('-').map(Number);return mo===1?`${y-1}-12`:`${y}-${n2(mo-1)}`};
const fmt=(d,opt={day:'numeric',month:'short'})=>dayOf(d).toLocaleDateString('en-GB',{timeZone:'UTC',...opt});
const mondays=month=>{let w=monday(`${month}-01`);if(w.slice(0,7)!==month)w=addDays(w,7);const a=[];while(w.slice(0,7)===month){a.push(w);w=addDays(w,7)}return a};
const isDoneWeek=(week,today)=>addDays(week,6)<today;
let approvedMonth='',adminCycle='',B=null,S=null,tab='home',selectedWorkout='push',adminMonth='',forfeitView='',calendarMonth='',loading=false,formPhoto='',wallPhoto='',lastProof='',pin={id:'',mode:'enter',buf:'',first:'',claimCode:'',busy:false},selection=0;
