const cycleStart=day=>{const anchor=dayOf('2026-11-02').getTime(),time=dayOf(monday(day)).getTime(),cycle=Math.floor((time-anchor)/(28*86400000));return addDays('2026-11-02',cycle*28)};
const cycleWeek=day=>Math.round((dayOf(monday(day))-dayOf(cycleStart(day)))/(7*86400000));
const cycleRule=day=>S?.cycleRules?.find(r=>r.start===cycleStart(day))||{start:cycleStart(day),target:4,forfeits:(S?.defaults||fallback).slice(0,4)};
