const archiveCycles=()=>{const dates=['2026-11-02',...(S?.checkins||[]).map(c=>c.day),...(S?.cycleRules||[]).map(c=>c.start)].sort();const first=cycleStart(dates[0]);const current=cycleStart(today());const cycles=[];for(let start=addDays(current,56),i=0;i<240&&start>=first;start=addDays(start,-28),i++)cycles.push(start);return cycles};
const monthName=m=>fmt(`${m}-01`,{month:'long',year:'numeric'});
