function demoSeed(){const t=localToday(),w=monday(t),m=w.slice(0,7),mk=(id,n)=>Array.from({length:n},(_,i)=>({id:`demo-${id}-${i}`,profileId:id,day:addDays(w,i),week:w,kind:['push','pull','legs'][i%3],note:'Sample workout',status:'approved',createdAt:ts()-i*9000,hasProof:false}));return {today:t,auth:null,profiles:[{id:'you',name:'Your profile',avatar:'',claimed:true,isAdmin:true,pin:'1234'},{id:'alex',name:'Alex',avatar:'',claimed:true,isAdmin:false,pin:'1234'},{id:'priya',name:'Priya',avatar:'',claimed:true,isAdmin:false,pin:'1234'},{id:'sam',name:'Sam',avatar:'',claimed:true,isAdmin:false,pin:'1234'}],checkins:[...mk('alex',4),...mk('priya',3),...mk('sam',2)],rules:[],defaults:fallback,done:[],cycleRules:[],proposals:[],proposalVotes:[],mvpVotes:[],mvpCrown:null,proofs:{},reactions:[],wallpapers:{}}}
let D=null;function saveD(){try{localStorage.setItem(previewKey,JSON.stringify(D))}catch{/* Some file:// browsers disallow local storage; demo remains in-memory */}};function initD(){try{D=JSON.parse(localStorage.getItem(previewKey))||demoSeed()}catch{D=demoSeed()}D.today=localToday();D.cycleRules ||= [];D.reactions ||= [];D.wallpapers ||= {};D.mvpCrown ||= null;D.jukebox ||= {url:'',title:'',selectedBy:null,updatedAt:0};saveD()}
function demoReq(url,method,b){if(!D)initD();const clone=()=>JSON.parse(JSON.stringify(D));const prof=id=>D.profiles.find(p=>p.id===id);if(url==='/api/bootstrap')return {setupRequired:false,profiles:D.profiles.map(({pin,...p})=>p),me:prof(D.auth)?((({pin,...p})=>p)(prof(D.auth))):null,today:D.today};if(url==='/api/login'){const p=prof(b.profileId);if(!p||p.pin!==b.pin)throw Error('Incorrect demo PIN (try 1234)');D.auth=p.id;saveD();return{ok:true}}if(url==='/api/claim'){const p=prof(b.profileId);if(!p||p.code!==b.claimCode)throw Error('Invalid invitation code');p.pin=b.pin;p.claimed=true;D.auth=p.id;saveD();return{ok:true}}if(url==='/api/logout'){D.auth=null;saveD();return{ok:true}}if(!D.auth)throw Error('Choose a profile');if(url==='/api/state'){const a=clone(),m=prof(D.auth);a.me=(({pin,...p})=>p)(m);a.profiles=a.profiles.map(({pin,code,...p})=>p);a.wallpaper=D.wallpapers[D.auth]||{theme:'ember',dim:.18,photo:''};a.jukebox=D.jukebox;a.feed=D.checkins.filter(c=>c.shareToFeed&&c.status==='approved'&&c.hasProof).map(c=>({id:c.id,profileId:c.profileId,kind:c.kind,day:c.day,note:c.note,createdAt:c.createdAt,myReaction:D.reactions.find(r=>r.checkinId===c.id&&r.profileId===D.auth)?.emoji||'',reactions:['🔥','👏','💪','❤️','🏆'].map(emoji=>({emoji,count:D.reactions.filter(r=>r.checkinId===c.id&&r.emoji===emoji).length}))}));return a}if(url==='/api/admin/mvp/crown'&&method==='POST'){if(!prof(b.profileId))throw Error('Unknown member');D.mvpCrown={profileId:b.profileId,source:'admin',awardedAt:ts()};saveD();return{ok:true,mvpCrown:D.mvpCrown}}if(url==='/api/admin/mvp/finalize'&&method==='POST'){const vs=D.mvpVotes.filter(v=>v.start===b.start),t={};vs.forEach(v=>t[v.candidateId]=(t[v.candidateId]||0)+1);const sorted=Object.entries(t).sort((a,b)=>b[1]-a[1]);if(!sorted.length||sorted[1]?.[1]===sorted[0][1])throw Error('No unique MVP winner');D.mvpCrown={profileId:sorted[0][0],source:'vote',cycleStart:b.start,awardedAt:ts()};saveD();return{ok:true,mvpCrown:D.mvpCrown}}if(url==='/api/jukebox'&&method==='POST'){D.jukebox={url:b.url,title:b.title||'SoundCloud track',selectedBy:D.auth,updatedAt:ts()};saveD();return{ok:true,jukebox:D.jukebox}}const removed=url.match(/^\/api\/admin\/checkins\/(.*?)\/delete$/);if(removed&&method==='POST'){const c=D.checkins.find(x=>x.id===removed[1]);if(!c||c.status!=='approved')throw Error('Only approved sessions can be removed');c.status='deleted';c.shareToFeed=false;saveD();return{ok:true}}if(url==='/api/me/wallpaper'&&method==='PATCH'){D.wallpapers[D.auth]=b;saveD();return{ok:true}}if(url==='/api/admin/checkins'&&method==='POST'){if(D.checkins.filter(c=>c.profileId===b.profileId&&c.day===b.day&&c.status!=='deleted').length>=20)throw Error('Daily safety limit reached');D.checkins.unshift({id:'manual-'+ts(),profileId:b.profileId,day:b.day,week:monday(b.day),kind:b.kind,note:b.note||'',status:'approved',createdAt:ts(),hasProof:false,adminAdded:true,shareToFeed:false});saveD();return{ok:true}}const vis=url.match(/^\/api\/checkins\/(.*?)\/visibility$/);if(vis){const c=D.checkins.find(x=>x.id===vis[1]);if(!c||c.profileId!==D.auth)throw Error('Not your session');c.shareToFeed=b.visible;saveD();return{ok:true}}const react=url.match(/^\/api\/feed\/(.*?)\/react$/);if(react){const c=D.checkins.find(x=>x.id===react[1]);if(!c?.shareToFeed)throw Error('Not published');const old=D.reactions.find(r=>r.checkinId===c.id&&r.profileId===D.auth);D.reactions=D.reactions.filter(r=>!(r.checkinId===c.id&&r.profileId===D.auth));if(old?.emoji!==b.emoji)D.reactions.push({checkinId:c.id,profileId:D.auth,emoji:b.emoji});saveD();return{ok:true}}if(url==='/api/checkins'&&method==='POST'){if(D.checkins.filter(c=>c.profileId===D.auth&&c.day===D.today&&c.status!=='deleted').length>=20)throw Error('Daily safety limit reached');D.checkins.unshift({id:'demo-'+ts(),profileId:D.auth,day:D.today,week:monday(D.today),kind:b.kind,note:b.note,status:'pending',createdAt:ts(),hasProof:true,shareToFeed:b.shareToFeed===true});D.proofs[D.checkins[0].id]=b.proof;saveD();return{ok:true}}const proof=url.match(/^\/api\/checkins\/(.*?)\/proof$/);if(proof)return{proof:D.proofs[proof[1]]||''};const review=url.match(/^\/api\/checkins\/(.*?)\/review$/);if(review){const c=D.checkins.find(x=>x.id===review[1]);if(c)c.status=b.status}if(url==='/api/profiles'&&method==='POST'){const id='p'+ts(),code=Math.random().toString(36).slice(2,10).toUpperCase();D.profiles.push({id,name:b.name,avatar:b.avatar||'',claimed:false,isAdmin:false,pin:'',code});saveD();return{ok:true,inviteCode:code,profileId:id}}const edit=url.match(/^\/api\/profiles\/(.*?)$/);if(edit&&method==='PATCH'){const p=prof(edit[1]);p.name=b.name||p.name;if(b.avatar!==undefined)p.avatar=b.avatar}const reset=url.match(/^\/api\/profiles\/(.*?)\/reset$/);if(reset&&method==='POST'){const p=prof(reset[1]);p.pin='';p.claimed=false;p.code=Math.random().toString(36).slice(2,10).toUpperCase();saveD();return{inviteCode:p.code}}if(url==='/api/cycle-rules'&&method==='POST'){D.cycleRules=(D.cycleRules||[]).filter(r=>r.start!==b.start).concat(b)}if(url==='/api/rules'&&method==='POST'){D.rules=D.rules.filter(r=>r.month!==b.month).concat(b)}if(url==='/api/forfeit-completed'&&method==='POST'){const x=D.done.find(z=>z.profileId===b.profileId&&z.week===b.week);if(x)x.completed=x.completed?0:1;else D.done.push({month:b.week.slice(0,7),week:b.week,profileId:b.profileId,completed:1})}if(url==='/api/proposals'&&method==='POST'){D.proposals.push({id:'prop'+ts(),profileId:D.auth,createdAt:ts(),...b})}if(url==='/api/proposal-votes'&&method==='POST'){D.proposalVotes=D.proposalVotes.filter(x=>x.start!==addDays(cycleStart(D.today),28)||x.voterId!==D.auth);D.proposalVotes.push({start:addDays(cycleStart(D.today),28),voterId:D.auth,proposalId:b.proposalId})}if(url==='/api/apply-proposal'&&method==='POST'){const p=D.proposals.find(x=>x.id===b.proposalId);D.cycleRules=D.cycleRules.filter(x=>x.start!==p.start).concat({start:p.start,target:4,forfeits:p.forfeits})}if(url==='/api/mvp-votes'&&method==='POST'){if(D.mvpVotes.some(x=>x.start===b.start&&x.voterId===D.auth))throw Error('You have already voted');D.mvpVotes.push({start:b.start,voterId:D.auth,candidateId:b.candidateId,createdAt:ts()})}saveD();return{ok:true}}
async function api(url,method='GET',body){if(demoMode)return demoReq(url,method,body);const response=await fetch(url,{method,credentials:'same-origin',headers:method==='GET'?{}:{'content-type':'application/json'},body:method==='GET'?undefined:JSON.stringify(body||{})});let result;try{result=await response.json()}catch{throw Error(`Server returned ${response.status}`)}if(!response.ok)throw Error(result.error||'Request failed');return result}
let toastTimer;function toast(v){const e=q('#toast');e.textContent=v;e.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('visible'),3000)}
function setWallpaper(){let t={theme:'ember',dim:.18,photo:'',textColor:'default'};try{t={...t,...(S?.wallpaper||JSON.parse(localStorage.getItem('gymclo_wallpaper')||'{}'))}}catch{}const b=q('#wallpaper');b.className=t.photo?'':t.theme;b.style.backgroundImage=t.photo?`url(${JSON.stringify(t.photo)})`:'';document.documentElement.style.setProperty('--shade',t.dim);const shades={default:'#f6f3f5',rose:'#ffd5da',ice:'#d8edff',mint:'#d7ffe7',gold:'#ffe7bb',lavender:'#e7d6ff',warm:'#fff3e7'};document.documentElement.style.setProperty('--ink',shades[t.textColor]||shades.default);return t}
async function saveWallpaper(update){const t={...setWallpaper(),...update};if(S&&!demoMode){await api('/api/me/wallpaper','PATCH',t);S.wallpaper=t}else{try{localStorage.setItem('gymclo_wallpaper',JSON.stringify(t))}catch{throw Error('Wallpaper too large for browser storage')}if(S)S.wallpaper=t}setWallpaper()}

function top(){const u=me();return `<header class="head"><div class="head-brand"><div class="wordmark">gymclo<i>.</i></div><div class="subtitle">THE FOUR-DAY STANDARD · ${esc(monthName(activeMonth()).toUpperCase())}</div></div><div class="head-right">${u?.isAdmin?`<button type="button" class="top-admin ${tab==='admin'?'active':''}" data-act="admin" aria-label="Open admin controls">${I('shield',17)}<span>Admin</span></button>`:''}<button class="icon-btn" data-act="wallpaper" aria-label="Change wallpaper" title="Wallpaper">${I('palette',19)}</button><button class="icon-btn" data-act="profile" aria-label="Your profile">${avatar(u,'sm')}</button></div></header>`}
