function progress(c,n){const r=54,C=2*Math.PI*r,offset=C*(1-Math.min(c/n,1));return `<div class="ring-wrap"><svg viewBox="0 0 140 140" role="img" aria-label="${c} of ${n} workouts"><circle class="ring-bg" cx="70" cy="70" r="54"></circle><circle class="ring-fg" cx="70" cy="70" r="54" style="--offset:${offset}"></circle></svg><div class="ring-number"><span class="num">${c}<span style="color:var(--muted);font-size:18px">/${n}</span></span><small>this week</small></div></div>`}
function todayLogged(){return S.checkins.some(c=>c.profileId===me().id&&c.day===today()&&!['deleted','rejected'].includes(c.status))}
