function validSoundcloudUrl(raw){try{const u=new URL(raw);return u.protocol==='https:'&&['soundcloud.com','www.soundcloud.com','m.soundcloud.com'].includes(u.hostname)&&u.pathname.split('/').filter(Boolean).length>=2}catch{return false}}
function vinylCard(){
  const track=S?.jukebox||{url:''},p=profile(track.selectedBy),has=!!track.url;
  const source=has?'https://w.soundcloud.com/player/?url='+encodeURIComponent(track.url)+'&auto_play=false&color=%23eb6975&show_artwork=false&show_user=true&sharing=false&buying=false&download=false&visual=false&show_comments=false':'';
  return `<section class="card vinyl-card" aria-label="SoundCloud vinyl music player"><div class="card-head"><div><div class="eyebrow">THE CREW'S SOUNDTRACK</div><h2 class="section-title" style="margin-top:4px">Now spinning.</h2></div><span class="pill">SoundCloud</span></div><div class="vinyl-main"><button type="button" id="vinylDisc" class="vinyl-disc" data-act="vinylToggle" aria-label="${has?'Play or pause the selected track':'Choose a track to play'}" aria-pressed="false"><span class="vinyl-label"><img id="vinylArtwork" alt="" hidden><span id="vinylFallback">${I('spark',28)}</span></span><span id="vinylPlayIndicator" class="vinyl-play-indicator">▶</span></button><div class="vinyl-info"><div class="label">Selected track</div><div id="vinylTitle" class="vinyl-title">${esc(has?track.title:'No track selected')}</div><p class="micro" style="margin-top:6px">${has?'Chosen by '+esc(p?.name||'a crew member'):'Anyone in the crew can choose a song.'}</p><p class="micro" id="vinylPlaybackStatus" style="margin-top:10px">${has?'Tap the vinyl to play. Tap again to pause.':'Paste a public SoundCloud link below.'}</p>${has?`<a class="vinyl-source" href="${esc(track.url)}" target="_blank" rel="noopener noreferrer">Listen on SoundCloud ↗</a>`:''}</div></div>${has?`<iframe id="soundcloudWidget" class="soundcloud-widget" title="Official SoundCloud player" src="${esc(source)}" loading="eager" allow="autoplay" referrerpolicy="strict-origin-when-cross-origin"></iframe>`:''}<form data-form="jukebox" class="vinyl-picker"><label class="field" for="soundcloudUrl">Choose a SoundCloud track or playlist</label><div class="vinyl-picker-row"><input class="input" name="url" id="soundcloudUrl" type="url" required placeholder="https://soundcloud.com/artist/song" aria-label="SoundCloud link"><button class="btn small" type="submit">Set track</button></div><div class="micro" style="margin-top:9px">Changing the track updates the crew's selection. Playback never starts automatically.</div></form></section>`
}
function loadScApi(){if(window.SC?.Widget)return Promise.resolve();if(scApiPromise)return scApiPromise;scApiPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://w.soundcloud.com/player/api.js';script.async=true;script.onload=resolve;script.onerror=()=>{scApiPromise=null;reject(Error('SoundCloud player could not load'))};document.head.append(script)});return scApiPromise}
function setVinylPlaying(on){
 scPlaying=!!on;
 const disc=q('#vinylDisc');if(disc){disc.classList.toggle('playing',scPlaying);disc.setAttribute('aria-pressed',String(scPlaying));disc.setAttribute('aria-label',scPlaying?'Pause SoundCloud':'Play SoundCloud')}
 const label=q('#vinylPlaybackStatus');if(label)label.textContent=scPlaying?'Playing · tap the vinyl to pause':'Paused · tap the vinyl to play';
 const indicator=q('#vinylPlayIndicator');if(indicator)indicator.textContent=scPlaying?'Ⅱ':'▶';
 const mini=q('#music-mini');if(mini){mini.classList.toggle('playing',scPlaying);const button=q('#mini-toggle');if(button){button.textContent=scPlaying?'Ⅱ':'▶';button.setAttribute('aria-label',scPlaying?'Pause SoundCloud':'Play SoundCloud')}const status=q('#mini-status');if(status)status.textContent=scPlaying?'Playing':'Paused'}
}
function updateVinylArtwork(sound){if(!sound)return;scCurrentTitle=sound.title||scCurrentTitle;const miniTitle=q('#mini-title');if(miniTitle&&scCurrentTitle)miniTitle.textContent=scCurrentTitle;if(!q('#vinylArtwork'))return;const art=sound.artwork_url||sound.user?.avatar_url||'';if(/^https:\/\//.test(art)){const img=q('#vinylArtwork');img.src=art.replace(/-large(?=\.)/,'-t500x500');img.hidden=false;const fallback=q('#vinylFallback');if(fallback)fallback.hidden=true;}const title=q('#vinylTitle');if(title&&sound.title)title.textContent=sound.title}
function mountSoundcloud(){const frame=q('#soundcloudWidget');if(!frame){scPlayer=null;scReady=false;scMountedFrame=null;scPlaying=false;return}if(scMountedFrame===frame&&scPlayer)return;scPlayer=null;scReady=false;scPlaying=false;scMountedFrame=frame;loadScApi().then(()=>{if(!frame.isConnected||q('#soundcloudWidget')!==frame)return;const widget=window.SC.Widget(frame);scPlayer=widget;widget.bind(window.SC.Widget.Events.READY,()=>{if(q('#soundcloudWidget')!==frame)return;scReady=true;widget.getCurrentSound(updateVinylArtwork);widget.isPaused(paused=>setVinylPlaying(!paused))});widget.bind(window.SC.Widget.Events.PLAY,()=>{if(frame.isConnected){setVinylPlaying(true);widget.getCurrentSound(updateVinylArtwork)}});widget.bind(window.SC.Widget.Events.PAUSE,()=>setVinylPlaying(false));widget.bind(window.SC.Widget.Events.FINISH,()=>setVinylPlaying(false));widget.bind(window.SC.Widget.Events.ERROR,()=>{setVinylPlaying(false);const label=q('#vinylPlaybackStatus');if(label)label.textContent='Track unavailable in the embedded player. Try another song.'})}).catch(err=>{const label=q('#vinylPlaybackStatus');if(label)label.textContent=err.message})}
function toggleVinyl(){if(!S?.jukebox?.url){q('#soundcloudUrl')?.focus();toast('Paste a SoundCloud link to select a track');return}if(!scPlayer||!scReady){toast('SoundCloud is loading. Tap the vinyl again shortly.');return}if(scPlaying)scPlayer.pause();else scPlayer.play()}

function syncMusicDeck(){
 const deck=q('#music-deck'),mini=q('#music-mini');
 if(!S||!deck||!mini){return}
 const key=S.jukebox?.url||'';
 if(scTrackKey!==key||!deck.firstElementChild){
  scTrackKey=key;scCurrentTitle=S.jukebox?.title||'SoundCloud track';
  if(scPlayer){try{scPlayer.pause()}catch{}}
  scPlayer=null;scReady=false;scMountedFrame=null;scPlaying=false;
  deck.innerHTML=vinylCard();
  if(key)mountSoundcloud();
 }
 const visible=tab==='home';
 deck.classList.toggle('music-deck-parked',!visible);
 mini.hidden=visible||!key;
 if(key){mini.innerHTML=`<div class="mini-art">${I('fire',19)}</div><div class="mini-copy"><div id="mini-title" class="mini-title">${esc(scCurrentTitle||S.jukebox?.title||'SoundCloud')}</div><div id="mini-status" class="mini-sub">${scPlaying?'Playing':'Paused'} · SoundCloud</div></div><button id="mini-toggle" type="button" data-act="vinylToggle" aria-label="${scPlaying?'Pause':'Play'} SoundCloud">${scPlaying?'Ⅱ':'▶'}</button><button type="button" class="mini-home" data-act="nav" data-value="home" aria-label="Open music player">${I('arrow',17)}</button>`}
 setVinylPlaying(scPlaying);
}
function home(){const w=activeWeek(),c=weekCount(me().id,w),n=target(),remaining=Math.max(0,n-c),remainingDays=7-(dayOf(today()).getUTCDay()+6)%7,ms=profiles(),total=ms.filter(p=>weekHit(p.id,w)).length;return `${top()}<section class="card hero"><div class="hero-copy"><div class="eyebrow">YOUR WEEK AT A GLANCE</div><div class="hero-big">${c>=n?'Made it.':'Keep the\npace.'}</div><p>${c>=n?'Four gym days. One standard. You showed up.':`${remaining} more gym day${remaining!==1?'s':''} to reach your target.`}</p><button class="btn small" style="margin-top:18px" data-act="nav" data-value="log" >${I('log',15)} Log workout</button></div>${progress(c,n)}</section><div class="metric-grid"><div class="metric"><div class="label">Crew finished</div><div class="value num">${total}<span style="color:var(--muted);font-size:15px">/${ms.length}</span></div></div><div class="metric"><div class="label">Days left</div><div class="value num">${remainingDays}</div></div><div class="metric"><div class="label">Your streak</div><div class="value em num">${streak(me().id)} <span style="font-size:14px">wk</span></div></div></div><div class="section-head"><h2 class="section-title">The crew</h2><span class="micro">MON — SUN</span></div><div class="card">${ms.map(p=>{const count=weekCount(p.id,w),days=new Set(weekCheckins(p.id,w).map(x=>x.day));return `<div class="list-row">${avatar(p,'md')}<div class="grow"><div class="row-name">${displayName(p)} ${p.id===me().id?'<span class="red">· you</span>':''}</div><div class="week-pips">${Array.from({length:7},(_,i)=>{const d=addDays(w,i);return `<span class="day-pip ${days.has(d)?'hit':''} ${d===today()?'today':''}" title="${esc(fmt(d))}"></span>`}).join('')}</div></div>${pill(count,n)}</div>`}).join('')}</div><div class="section-head"><h2 class="section-title">Next up</h2><span class="micro">WEEK ${cycleWeek(w)+1} OF 4</span></div><div class="card soft"><div class="label">This week's forfeit if you fall short</div><h3 class="section-title" style="margin-top:9px;color:var(--red-light)">${esc(cycleRule(w).forfeits[cycleWeek(w)]||fallback[cycleWeek(w)])}</h3><p class="section-desc" style="margin:9px 0 0">The challenge increases each week, whether or not you previously missed a target.</p></div>${demoMode?'<div class="support-note" style="margin-top:14px">PREVIEW MODE · demo PIN is <b>1234</b>. Entries on this file are only saved on this device.</div>':''}`}
function streak(id){let w=activeWeek(),n=0;if(!weekHit(id,w))w=addDays(w,-7);while(n<52&&weekHit(id,w)){n++;w=addDays(w,-7)}return n}
function archiveMonths(){const dates=S.checkins.map(c=>c.day).filter(d=>/^20\d{2}-\d{2}-\d{2}$/.test(d));const earliest=[...dates.map(d=>d.slice(0,7)),'2026-11'].sort()[0];const a=[];for(let m=activeMonth(),i=0;i<240&&m>=earliest;m=prevMonth(m),i++)a.push(m);return a}
function archivePicker(m,kind){return `<label class="field" for="${kind}Archive">Select month</label><select class="input" id="${kind}Archive" data-archive="${kind}">${archiveMonths().map(x=>`<option value="${x}" ${x===m?'selected':''}>${esc(monthName(x))}${x===activeMonth()?' · Current':' · Archive'}</option>`).join('')}</select>`}
function logPage(){const w=activeWeek(),c=weekCount(me().id,w),n=cycleRule(w).target,logged=todayLogged(),m=calendarMonth||activeMonth(),mine=S.checkins.filter(x=>x.profileId===me().id&&x.day.startsWith(m)).sort((a,b)=>b.day.localeCompare(a.day)),mineDays=new Set(mine.filter(x=>!['rejected','deleted'].includes(x.status)).map(x=>x.day)).size;return `${top()}<div class="eyebrow">WORKOUT JOURNAL</div><h1 style="font-size:29px;letter-spacing:-.06em;margin:6px 0 7px">Your attendance.</h1><p class="section-desc">A clear record of every gym day, with archives for previous months.</p><div class="card"><div class="log-head"><div><div class="label">This week</div><div class="log-count">${c}<span> / ${n}</span></div></div><span class="pill ${logged?'done':''}">${logged?'✓ Logged today':'Not logged today'}</span></div><div class="progress-mini"><i style="--pct:${Math.min(100,c/n*100)}%"></i></div><p class="micro" style="margin-top:12px">${todaySessions()} session${todaySessions()===1?'':'s'} logged today. Multiple sessions are welcome; each calendar day counts once toward your weekly target.</p><details class="log-form"><summary>${I('log',17)} Log today's workout ${I('arrow',17)}</summary><form data-form="checkin" style="padding-top:14px"><div class="label">Session type</div><div class="kind-grid">${[['push','Push'],['pull','Pull'],['legs','Legs'],['cardio','Cardio'],['other','Other']].map(([id,name])=>`<button type="button" data-act="kind" data-value="${id}" class="kind-chip ${selectedWorkout===id?'active':''}">${I(id==='cardio'?'clock':id==='other'?'spark':'log')}${name}</button>`).join('')}</div><label class="field" for="workoutNote">Notes (optional)</label><input class="input" id="workoutNote" maxlength="180" placeholder="What did you train?"><label class="field">Proof of attendance</label><div class="proof-uploader"><label class="proof-drop" for="checkinPhoto"><div class="proof-icon">${I('camera',22)}</div><div class="proof-copy"><strong id="proofUploadTitle">${formPhoto?'Image ready':'Attach workout evidence'}</strong><span>JPG, PNG or WebP · Private unless shared</span></div><span class="proof-browse">Choose image</span><input type="file" id="checkinPhoto" accept="image/*" aria-label="Select gym attendance photo"></label><div class="proof-preview ${formPhoto?'has-image':''}" id="proofPreview">${formPhoto?`<img alt="Selected proof" src="${formPhoto}"><span class="grow micro">Image attached successfully</span>`:''}<button type="button" class="proof-remove" data-act="clearProof">Remove</button></div></div><label class="share-option"><input type="checkbox" name="shareToFeed"><span><b>Share this achievement to the crew feed</b><span class="micro" style="display:block;margin-top:3px">Optional · off by default. Your photo appears only after it is approved.</span></span></label><button class="btn full" type="submit" style="margin-top:15px">Submit workout</button></form></details></div><div class="section-head"><h2 class="section-title">Attendance calendar</h2><span class="pill">${mineDays} day${mineDays===1?'':'s'}</span></div>${archivePicker(m,'calendar')}${calCard(me().id)}<div class="section-head"><h2 class="section-title">${esc(monthName(m))} sessions</h2></div><div class="card">${mine.length?mine.filter(x=>x.status!=='deleted').map(x=>`<div class="list-row"><div class="avatar md" style="background:var(--red-dim);color:var(--red-light)">${I('check',20)}</div><div class="grow"><div class="row-name">${fmt(x.day,{weekday:'short',day:'numeric',month:'short'})} · ${esc(x.kind)}</div><div class="row-sub">${esc(x.note||'Gym session')}</div></div>${x.adminAdded?'<span class="pill gold">Admin added</span>':''}${x.hasProof?`<button class="btn ghost small" data-act="proof" data-id="${x.id}">Proof</button><button class="btn outline small" data-act="shareSession" data-id="${x.id}">${x.shareToFeed?'Unshare':'Share'}</button>`:''}<span class="pill ${x.status==='rejected'?'risk':x.status==='approved'?'done':''}">${esc(x.status)}</span></div>`).join(''):'<p class="muted">No entries in this month.</p>'}</div>`}

function crewPage(){const start=cycleStart(today()),w=activeWeek(),listed=profiles().map(p=>({...p,c:weekCount(p.id,w),hits:totalHits(p.id,start),all:countAll(p.id,start),days:countCycleDays(p.id,start)})).sort((a,b)=>b.hits-a.hits||b.days-a.days||a.name.localeCompare(b.name));return `${top()}<div class="eyebrow">FOUR-WEEK CONSISTENCY</div><h1 class="section-title" style="font-size:29px;margin:7px 0">The leaderboard.</h1><p class="section-desc">Current challenge: ${fmt(start)} – ${fmt(addDays(start,27))}. Everyone is measured across exactly four weeks.</p>${crownBanner()}<div class="card">${listed.map((p,i)=>`<div class="list-row"><div class="score-rank ${i<3?'top':''}">${n2(i+1)}</div>${avatar(p,'md')}<div class="grow"><div class="row-name">${esc(p.name)} ${p.id===me().id?'<span class="red">· you</span>':''}</div><div class="row-sub">${p.hits}/4 weeks completed · ${p.days} gym day${p.days===1?'':'s'} · ${p.all} workouts</div><div class="progress-mini"><i style="--pct:${Math.min(100,Math.round(p.c/target()*100))}%"></i></div></div>${pill(p.c,target())}</div>`).join('')}</div><div class="section-head"><h2 class="section-title">Four-week highlights</h2></div><div class="metric-grid"><div class="metric"><div class="label">Crew workouts</div><div class="value num">${listed.reduce((n,x)=>n+x.all,0)}</div></div><div class="metric"><div class="label">Finished weeks</div><div class="value num">${listed.reduce((n,x)=>n+x.hits,0)}</div></div><div class="metric"><div class="label">Perfect cycles</div><div class="value em num">${listed.filter(x=>eligible(x.id,start)).length}</div></div></div><div class="section-head"><h2 class="section-title">Your calendar</h2></div>${calCard(me().id)}`}
const messageGifUrl=m=>m?.gifId?`https://giphy.com/embed/${esc(m.gifId)}`:'';
const handle=p=>'@'+(p?.name||'member').toLowerCase().replace(/[^a-z0-9]+/g,'').slice(0,25);
function messageCard(m,replies=[]){const p=profile(m.profileId),own=me()?.id===m.profileId;return `<article class="${m.parentId?'chat-reply':'card chat-card'}"><div class="chat-author">${avatar(p,'sm')}<div class="grow"><div class="feed-handle">${esc(handle(p))} ${crowned(p)?'💎👑':''}</div><div class="micro">${new Date(m.createdAt).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}${m.editedAt?' · edited':''}</div></div>${own?`<button class="btn ghost small" data-act="editChat" data-id="${m.id}">${I('pen',14)} Edit</button>`:''}</div>${m.text?`<p style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(m.text)}</p>`:''}${m.hasImage?`<img class="chat-photo" src="/api/messages/${m.id}/image" loading="lazy" alt="Image attached by ${esc(handle(p))}">`:''}${m.gifId?`<iframe title="GIF reply from GIPHY" class="gif-frame" loading="lazy" src="${messageGifUrl(m)}" allowfullscreen></iframe><div class="micro">Powered by GIPHY</div>`:''}<div class="chat-actions">${m.reactions.map(r=>`<button class="reaction ${m.myReaction===r.emoji?'selected':''}" data-act="chatReact" data-id="${m.id}" data-value="${r.emoji}">${r.emoji} ${r.count||''}</button>`).join('')}${!m.parentId?`<button class="btn ghost small" data-act="replyChat" data-id="${m.id}">${I('log',13)} Reply ${replies.length?`(${replies.length})`:''}</button>`:''}</div>${replies.length?`<div class="chat-replies">${replies.map(x=>messageCard(x)).join('')}</div>`:''}</article>`}
function chatBoard(){const messages=S.messages||[],roots=messages.filter(m=>!m.parentId),replies=messages.filter(m=>m.parentId);return `<div class="section-head" style="margin-top:2px"><h2 class="section-title">Crew chat</h2><span class="pill">Everyone can post</span></div><div class="card chat-composer"><form data-form="chatPost"><label class="field" for="chatText">Say something to the crew</label><textarea id="chatText" name="text" class="input" maxlength="1000" placeholder="What's happening today? Share a win, a plan, or just a thought…"></textarea><div class="chat-composer-inputs"><label class="micro">Attach an image<input type="file" class="input" name="image" accept="image/*"></label><label class="micro">GIF link (optional)<input class="input" name="gifUrl" placeholder="Paste a GIPHY link"></label></div><button class="btn full" type="submit">Post to crew chat</button></form><div class="micro" style="margin-top:11px">Messages are visible to all signed-in members. Edit your posts at any time.</div></div>${roots.length?roots.map(m=>messageCard(m,replies.filter(x=>x.parentId===m.id))).join(''):'<div class="support-note">No messages yet — start the conversation.</div>'}<div class="divider"></div>`}
function chatModal(parentId='',id=''){const message=(S.messages||[]).find(m=>m.id===id),isReply=!!parentId;const currentGif=message?.gifId?`https://giphy.com/embed/${message.gifId}`:'';openModal({title:id?'Edit your message':isReply?'Reply to the crew':'New message',body:`<form data-form="${id?'chatEdit':'chatPost'}" data-id="${esc(id)}" data-parent="${esc(parentId||message?.parentId||'')}"><label class="field">Message</label><textarea class="input" name="text" maxlength="1000" rows="4" placeholder="Your message…">${esc(message?.text||'')}</textarea><label class="field">Attach photo ${message?.hasImage?'(replace existing photo if needed)':''}</label><input class="input" type="file" name="image" accept="image/*">${message?.hasImage?'<label class="micro"><input type="checkbox" name="removeImage"> Remove existing photo</label>':''}<label class="field">GIPHY reaction</label><input class="input" name="gifUrl" id="gifInput" value="${esc(currentGif)}" placeholder="Paste a giphy.com/gifs/... link">${S.giphyEnabled?`<label class="field">Search GIPHY</label><div class="chat-composer-inputs"><input class="input" id="gifSearch" placeholder="Search GIFs…"><button class="btn ghost" type="button" data-act="gifSearch">Search</button></div><div class="gif-search-results" id="gifResults"></div><div class="micro">Powered by GIPHY</div>`:'<div class="micro" style="margin-top:8px">Find a GIF on GIPHY and paste its share link above. In-app searching can be enabled with a GIPHY API key.</div>'}<button class="btn full" type="submit" style="margin-top:13px">${id?'Save changes':'Post reply'}</button></form>`})}
function feedPage(){const items=S.feed||[];return `${top()}${chatBoard()}<div class="eyebrow">SHOW UP. SHARE THE WIN.</div><h1 class="section-title" style="font-size:29px;margin:7px 0">The crew feed.</h1><p class="section-desc">Only achievements members choose to share appear here. Photos stay private by default and posts appear after approval.</p>${items.length?items.map(post=>{const p=profile(post.profileId),handle='@'+(p?.name||'member').toLowerCase().replace(/[^a-z0-9]+/g,'').slice(0,25);const src=demoMode?D?.proofs?.[post.id]:`/api/feed/${post.id}/image`;return `<article class="card feed-card"><div class="feed-intro">${avatar(p,'md')}<div class="grow"><div class="feed-handle">${esc(handle)}</div><div class="micro">${displayName(p)} · ${fmt(post.day,{weekday:'short',day:'numeric',month:'short',year:'numeric'})}</div></div><span class="pill done">${esc(post.kind)}</span></div>${src?`<img class="feed-media" src="${esc(src)}" alt="Gym achievement shared by ${esc(p?.name||'member')}" loading="lazy">`:''}<div class="feed-content">${post.note?`<p>${esc(post.note)}</p>`:''}<div class="feed-reactions">${post.reactions.map(r=>`<button type="button" class="reaction ${post.myReaction===r.emoji?'selected':''}" data-act="react" data-id="${post.id}" data-value="${r.emoji}" aria-label="React ${r.emoji}, ${r.count} reactions">${r.emoji} <span class="micro">${r.count||''}</span></button>`).join('')}</div></div></article>`}).join(''):'<div class="card"><div class="section-title">No public achievements yet.</div><p class="section-desc" style="margin-top:8px">When logging a gym photo, tick “Share this achievement” to post it to the feed after approval.</p><button class="btn small" data-act="nav" data-value="log">Go to Log</button></div>'}`}

function calCard(id){const month=calendarMonth||activeMonth(),[y,mo]=month.split('-').map(Number),days=new Date(Date.UTC(y,mo,0)).getUTCDate(),offset=(dayOf(`${month}-01`).getUTCDay()+6)%7,hits=new Set(S.checkins.filter(x=>x.profileId===id&&x.status!=='rejected'&&x.status!=='deleted').map(x=>x.day));return `<div class="card"><div class="card-head"><button class="icon-btn" data-act="cal" data-value="-1" aria-label="Previous month">${I('back',17)}</button><h3 class="section-title">${monthName(month)}</h3><button class="icon-btn" data-act="cal" data-value="1" aria-label="Next month" ${month>=activeMonth()?'disabled':''}>${I('arrow',17)}</button></div><div class="calendar">${['M','T','W','T','F','S','S'].map(x=>`<div class="cal-h">${x}</div>`).join('')}${'<div></div>'.repeat(offset)}${Array.from({length:days},(_,i)=>{const d=`${month}-${n2(i+1)}`;return `<div class="cal-day ${hits.has(d)?'hit':''} ${d===today()?'today':''}" style="animation-delay:${Math.min(i,21)*15}ms">${i+1}</div>`}).join('')}</div></div>`}
function forfeitsPage(){const start=forfeitView||cycleStart(today()),weeks=cycleDates(start),r=cycleRule(start),owe=profiles().flatMap(p=>weeks.filter(w=>isDoneWeek(w,today())&&!weekHit(p.id,w)&&!forfeitDone(p.id,w)).map(w=>({p,w,index:weeks.indexOf(w)})));return `${top()}<div class="eyebrow">THE FOUR-WEEK CHALLENGE</div><h1 class="section-title" style="font-size:29px;margin:7px 0">Forfeit ladder.</h1><p class="section-desc">Four increasingly difficult fitness forfeits. The ladder resets after every four-week cycle; past cycles stay archived.</p><div class="card-head"><button class="btn ghost small" data-act="cycle" data-value="${addDays(start,-28)}">${I('back',15)} Previous</button><span class="pill">${fmt(start)} – ${fmt(addDays(start,27))}</span><button class="btn ghost small" data-act="cycle" data-value="${addDays(start,28)}" ${start>=cycleStart(today())?'disabled':''}>Next ${I('arrow',15)}</button></div><div class="ladder">${weeks.map((w,i)=>`<div class="forfeit-item ${w===activeWeek()?'active':''}"><div class="step-num">${i+1}</div><div class="grow"><div class="label">Week ${i+1} · ${fmt(w)} – ${fmt(addDays(w,6))}</div><div class="step-text">${esc(r.forfeits[i]||fallback[i])}</div><div class="micro" style="margin-top:7px">${w===activeWeek()?'Current week':isDoneWeek(w,today())?'Finished':'Upcoming'}</div></div></div>`).join('')}</div><div class="section-head"><h2 class="section-title">Outstanding forfeits</h2><span class="pill risk">${owe.length} due</span></div><div class="card">${owe.length?owe.map(x=>`<div class="list-row">${avatar(x.p,'md')}<div class="grow"><div class="row-name">${esc(x.p.name)} · Week ${x.index+1}</div><div class="row-sub">${esc(r.forfeits[x.index]||fallback[x.index])}</div></div>${me().isAdmin?`<button class="btn ghost small" data-act="markForfeit" data-id="${x.p.id}" data-value="${x.w}">Mark done</button>`:'<span class="pill risk">Due</span>'}</div>`).join(''):'<p class="muted">No outstanding forfeits for this cycle.</p>'}</div><div class="support-note" style="margin-top:15px">Fitness forfeits must be appropriate to each person's health and ability. Waive or adapt them when necessary.</div>`}

function votePage(){
 const current=cycleStart(today()),past=addDays(current,-28),next=addDays(current,28);
 const mvpCandidates=profiles().filter(p=>eligible(p.id,past));
 const mine=S.mvpVotes.find(x=>x.start===past&&x.voterId===me().id);
 const votes=S.mvpVotes.filter(x=>x.start===past);
 const proposals=S.proposals.filter(p=>p.start===next&&Array.isArray(p.forfeits)&&p.forfeits.length===4);
 const myProposal=S.proposalVotes.find(x=>x.start===next&&x.voterId===me().id);
 const nomineeRows=mvpCandidates.map(p=>{const n=votes.filter(v=>v.candidateId===p.id).length;let action='';if(mine){if(mine.candidateId===p.id)action='<span class="pill done">Your vote ✓</span>'}else if(p.id===me().id)action='<span class="pill">You</span>';else action=`<button class="btn small" data-act="mvp" data-id="${p.id}" data-value="${past}">Vote</button>`;return `<div class="vote-option">${avatar(p,'md')}<div class="grow"><div class="row-name">${displayName(p)}</div><div class="row-sub">${n} vote${n===1?'':'s'} · perfect four-week attendance</div></div>${action}</div>`}).join('');
 const proposalRows=proposals.map(p=>{const count=S.proposalVotes.filter(x=>x.proposalId===p.id).length,total=S.proposalVotes.filter(x=>x.start===next).length;const adminAction=me().isAdmin?`<button class="btn outline small" data-act="applyProposal" data-id="${p.id}">Apply</button>`:'';return `<div class="vote-option"><div class="grow"><div class="row-name">${esc(p.title)}</div><div class="row-sub">Proposed by ${esc(profile(p.profileId)?.name||'Member')} · ${count} votes</div><div class="micro" style="margin-top:8px">W1 ${esc(p.forfeits[0])} … W4 ${esc(p.forfeits[3])}</div>${total?`<div class="progress-mini"><i style="--pct:${count/total*100}%"></i></div>`:''}</div><div style="display:flex;flex-direction:column;align-items:flex-end;gap:6px"><button class="btn ${myProposal?.proposalId===p.id?'':'ghost'} small" data-act="proposalVote" data-id="${p.id}">${myProposal?.proposalId===p.id?'Voted ✓':'Vote'}</button>${adminAction}</div></div>`}).join('');
 return `${top()}<div class="eyebrow">A LITTLE HEALTHY COMPETITION</div><h1 class="section-title" style="font-size:29px;margin:7px 0">The voting room.</h1><p class="section-desc">Vote for a member who completed all four weeks, and choose the next set of four forfeits.</p><div class="card"><div class="card-head"><div><div class="eyebrow">THE CROWN</div><h2 class="section-title">Gym MVP · ${fmt(past)} – ${fmt(addDays(past,27))}</h2></div>${I('crown',29)}</div>${crownBanner()}${nomineeRows||'<div class="support-note">MVP nominees must complete the full previous four-week cycle.</div>'}${mine?'<p class="micro" style="margin-top:12px">One MVP vote per member. A clear winner is crowned once all claimed members have voted, or the admin finalizes the result.</p>':''}</div><div class="section-head"><h2 class="section-title">Next four-week forfeits</h2><span class="pill">${fmt(next)} – ${fmt(addDays(next,27))}</span></div><div class="card"><div class="card-head"><div class="micro">Every proposal has exactly four fitness challenges.</div><button class="btn outline small" data-act="propose">${I('log',14)} Propose</button></div>${proposalRows||'<p class="muted">No ideas yet. Submit a four-week challenge.</p>'}</div>`;
}

function adminPage(){const w=activeWeek(),pend=S.checkins.filter(c=>c.status==='pending').sort((a,b)=>Number(b.flagged||0)-Number(a.flagged||0)||b.createdAt-a.createdAt),m=adminMonth||activeMonth(),r=rule(m),ms=profiles();return `${top()}<div class="section-head"><h1 style="font-size:27px;letter-spacing:-.05em">Admin control room.</h1><span class="pill">OWNER ONLY</span></div>${crownBanner()}<div class="section-head"><h2 class="section-title">Diamond Crown MVP</h2><span class="pill">💎 ONE CURRENT MVP</span></div><div class="card"><p class="section-desc">Choose an initial MVP or award the crown manually in exceptional circumstances. Only one member holds it at a time; the crown stays until replaced.</p><form data-form="setMvpCrown" class="mvp-admin-controls"><div><label class="field">Crown this member</label><select class="input" name="profileId" required>${ms.map(p=>`<option value="${esc(p.id)}" ${S.mvpCrown?.profileId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><button class="btn" type="submit">💎 Award crown</button></form><div class="divider"></div><div class="label">Completed cycle results</div><p class="micro" style="margin:8px 0 12px">Finalize the previous cycle's MVP votes. A tied vote requires manually selecting the winner above.</p><button type="button" class="btn outline small" data-act="finalizeMvp" data-value="${addDays(cycleStart(today()),-28)}">${I('crown',15)} Crown last cycle's vote winner</button></div><p class="section-desc">Edit the current four-week forfeits below. Changes save for everyone immediately.</p><div class="section-head"><h2 class="section-title">Edit forfeits & rules</h2></div><form class="card" data-form="cycleRules"><p class="section-desc">Each cycle lasts exactly 28 days. Edit the four forfeits; the ladder automatically resets to Week 1 in the next cycle. Previous cycles remain saved.</p><label class="field">Cycle</label><select class="input" name="start" data-archive="adminCycle">${archiveCycles().map(d=>`<option value="${d}" ${d===(adminCycle||cycleStart(today()))?'selected':''}>${fmt(d)} – ${fmt(addDays(d,27))}</option>`).join('')}</select><label class="field">Distinct gym days per week</label><input class="input" name="target" type="number" min="1" max="7" required value="${cycleRule(adminCycle||cycleStart(today())).target}">${cycleRule(adminCycle||cycleStart(today())).forfeits.slice(0,4).map((f,i)=>`<label class="field">Week ${i+1} forfeit</label><input class="input" name="f${i}" maxlength="180" required value="${esc(f)}">`).join('')}<button class="btn full" style="margin-top:17px" type="submit">Save four-week forfeits</button></form><div class="section-head"><h2 class="section-title">Add a missed gym session</h2></div><form class="card" data-form="adminCheckin"><p class="section-desc">Backdate extra sessions for members who couldn't log in time. Multiple sessions per day are allowed, but that day counts only once. This is recorded as an admin correction, with no photo or feed post.</p><label class="field">Member</label><select class="input" name="profileId" required>${ms.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select><label class="field">Session date</label><input class="input" type="date" name="day" max="${today()}" value="${today()}" required><label class="field">Workout type</label><select class="input" name="kind">${[['push','Push'],['pull','Pull'],['legs','Legs'],['cardio','Cardio'],['other','Other']].map(([k,n])=>`<option value="${k}">${n}</option>`).join('')}</select><label class="field">Reason or notes (optional)</label><input class="input" name="note" maxlength="180" placeholder="Attendance entered by admin"><button class="btn full" style="margin-top:16px" type="submit">Save missed session</button></form><div class="card"><div class="card-head"><h3 class="section-title">Invite & manage profiles</h3><button class="btn small" data-act="addMember">${I('log',14)} Add member</button></div><p class="section-desc">Your friends need the website link, their own profile, and an invitation code to create a private PIN.</p><button type="button" class="btn outline small" data-act="copyLink">${I('copy',14)} Copy website link</button><div class="divider"></div>${ms.map(p=>`<div class="list-row">${avatar(p,'md')}<div class="grow"><div class="row-name">${esc(p.name)}</div><div class="row-sub">${p.isAdmin?'Owner':p.claimed?'PIN active':'Awaiting invitation'}</div></div><button class="btn ghost small" data-act="editMember" data-id="${p.id}">Edit</button>${!p.isAdmin?`<button class="btn outline small" data-act="resetPin" data-id="${p.id}">Reset PIN</button>`:''}</div>`).join('')}</div><div class="section-head"><h2 class="section-title">Evidence review</h2><span class="pill ${pend.length?'risk':''}">${pend.length} pending</span></div><div class="card"><p class="section-desc">Sessions count provisionally. Possible reused photos appear first; review those and anything else that looks suspicious.</p>${pend.slice(0,35).map(c=>`<div class="list-row">${avatar(profile(c.profileId),'sm')}<div class="grow"><div class="row-name">${esc(profile(c.profileId)?.name)} · ${fmt(c.day)}</div><div class="row-sub">${esc(c.note||c.kind)} ${c.flagged?'<span class="red"> · Possible reused photo</span>':''}</div></div><button class="btn ghost small" data-act="proof" data-id="${c.id}">Proof</button><button class="btn ghost small" data-act="review" data-id="${c.id}" data-value="approved">✓</button><button class="btn outline small" data-act="review" data-id="${c.id}" data-value="rejected">✕</button></div>`).join('')||'<p class="muted">Nothing to review.</p>'}</div><div class="section-head"><h2 class="section-title">Manage approved sessions</h2><span class="pill">${S.checkins.filter(c=>c.status==='approved').length} approved</span></div><div class="card"><p class="section-desc">Remove incorrect or duplicate approved sessions. Attendance credit is only removed when no other active sessions remain on that day. An audit record is preserved.</p><label class="field">Approved sessions from</label><select class="input" data-archive="approvedMonth" aria-label="Choose month to manage sessions">${archiveMonths().map(m=>`<option value="${m}" ${m===(approvedMonth||activeMonth())?'selected':''}>${monthName(m)}</option>`).join('')}</select><div class="divider"></div>${S.checkins.filter(c=>c.status==='approved'&&c.day.startsWith(approvedMonth||activeMonth())).sort((a,b)=>b.day.localeCompare(a.day)||b.createdAt-a.createdAt).map(c=>`<div class="list-row">${avatar(profile(c.profileId),'sm')}<div class="grow"><div class="row-name">${esc(profile(c.profileId)?.name||'Member')} · ${fmt(c.day)}</div><div class="row-sub">${esc(c.kind)}${c.adminAdded?' · Admin added':''}${c.note?' · '+esc(c.note):''}</div></div><button type="button" class="btn outline small" data-act="deleteSession" data-id="${c.id}">Delete</button></div>`).join('')||'<p class="muted">No approved sessions.</p>'}</div><div class="section-head"><h2 class="section-title">WhatsApp update</h2></div><div class="card"><p class="section-desc">Ready-to-paste weekly summary. You can send it directly to your WhatsApp group.</p><textarea class="input" id="summaryText" rows="10" readonly>${esc(summaryText())}</textarea><div class="button-row"><button class="btn" data-act="copySummary">${I('check',16)} Copy summary</button><button class="btn ghost" data-act="shareSummary">Share</button></div></div>`}
function summaryText(){const w=activeWeek(),r=cycleRule(w),n=r.target;return `🏋️ gymclo · Week of ${fmt(w)}\n\n${profiles().map(p=>`${weekCount(p.id,w)>=n?'✅':'⏳'} ${p.name}: ${weekCount(p.id,w)}/${n}`).join('\n')}\n\n🔥 This week's forfeit: ${r.forfeits[cycleWeek(w)]||r.forfeits[0]}\n\nLog your gym sessions: ${demoMode?'[add live link here]':location.origin}`}
function render(){setWallpaper();if(!S){nav.hidden=true;q('#music-mini').hidden=true;q('#music-deck').innerHTML='';scTrackKey='';scPlayer=null;scReady=false;return}let content=({home,log:logPage,crew:crewPage,feed:feedPage,forfeits:forfeitsPage,vote:votePage,admin:adminPage}[tab]||home)();el.innerHTML=content;drawNav();entry.hidden=true;nav.hidden=false;syncMusicDeck()}
async function refresh(){S=await api('/api/state');B={...B,profiles:S.profiles,me:S.me,today:S.today};render()}
async function boot(){setWallpaper();try{B=await api('/api/bootstrap');if(B.me){await refresh()}else{S=null;nav.hidden=true;renderEntry()}}catch(err){entry.hidden=false;entry.innerHTML=`<div class="entry-brand">gymclo<span class="red">.</span></div><div class="entry-title">Can't connect yet</div><p class="entry-sub">${esc(err.message)}. Check that the server is running.</p><button class="btn" style="margin-top:20px" data-act="reload">Try again</button>`}}
function renderEntry(){entry.hidden=false;nav.hidden=true;el.innerHTML='';if(B.setupRequired)return renderSetup();if(pin.id)return renderPin();const p=B.profiles;entry.innerHTML=`<div class="entry-brand">gymclo<span class="red">.</span></div><div class="eyebrow" style="margin-top:11px">YOUR CREW. YOUR CONSISTENCY.</div><h1 class="entry-title">Who's showing up?</h1><p class="entry-sub">Choose your profile to continue</p><div class="profile-gallery" id="profileGallery">${p.map((m,i)=>`<button class="profile-tile ${i===selection?'active':''}" style="--i:${i}" data-act="chooseProfile" data-id="${m.id}" data-index="${i}">${avatar(m,'xl')}<span class="profile-name">${esc(m.name)}</span><span class="micro">${m.claimed?'4-digit PIN':'Invite required'}</span></button>`).join('')}</div><p class="selector-foot">Swipe to explore · Each profile is personal</p><p class="micro" style="max-width:350px;text-align:center;margin-top:12px">New here? Ask your Gymclo admin to add your profile and send you a personal invitation code. You can then create your own four-digit PIN.</p>${demoMode?'<p class="support-note" style="margin-top:17px">DEMO ONLY · PIN for the sample profiles is <b>1234</b>.</p>':''}`;let g=q('#profileGallery');if(p.length>1)requestAnimationFrame(()=>{const chosen=qa('.profile-tile',g)[selection];chosen?.scrollIntoView({block:'nearest',inline:'center',behavior:'smooth'})});}
function renderSetup(){entry.innerHTML=`<div class="setup"><div class="entry-brand">gymclo<span class="red">.</span></div><div class="eyebrow" style="margin-top:16px">WELCOME TO YOUR NEW CLUB</div><h1 class="entry-title">Start the crew.</h1><p class="entry-sub">Create the admin profile first, then invite your friends. Only the creator needs the one-time setup code from the hosting dashboard.</p><form data-form="setup" style="margin-top:24px"><label class="field">Your name</label><input class="input" name="name" maxlength="28" required autocomplete="name" placeholder="Your name"><label class="field">One-time setup code</label><input class="input" name="setupCode" required placeholder="From hosting environment"><label class="field">Choose your four-digit PIN</label><input class="input" name="pin" inputmode="numeric" type="password" minlength="4" maxlength="4" pattern="[0-9]{4}" required placeholder="••••" autocomplete="new-password"><button class="btn full" style="margin-top:18px">Create gymclo</button></form></div>`}
function chooseProfile(id,index){selection=Number(index)||0;const p=B.profiles.find(x=>x.id===id);if(!p)return;pin={id,mode:p.claimed?'enter':'claim',buf:'',first:'',claimCode:'',busy:false};renderPin()}
function renderPin(){const p=B.profiles.find(x=>x.id===pin.id);if(!p){pin.id='';return renderEntry()}const mode=pin.mode,claim=mode==='claim',titles={enter:'Welcome back.',claim:'Claim your place.',create:'Create your PIN.',confirm:'One more time.'};entry.innerHTML=`<div class="pin-card">${avatar(p,'xxl')}<div class="entry-title" style="margin-top:25px">${esc(p.name)}</div><div class="entry-sub">${titles[mode]||titles.enter}</div>${claim?`<p class="entry-sub" style="margin-top:17px">Enter the private invitation code shared by your admin.</p><form data-form="claimCode" style="max-width:300px"><input class="input claim-code" name="code" required maxlength="48" placeholder="INVITATION CODE" autocapitalize="characters" autocomplete="off"><button class="btn full" style="margin-top:9px">Continue</button></form>`:`<div class="entry-sub" style="margin-top:8px" id="pinHelp">${mode==='confirm'?'Repeat your new four digits':mode==='create'?'Choose four digits only you know':'Enter your four-digit passcode'}</div><div class="pin-dots" id="pinDots">${Array.from({length:4},()=>'<span class="pin-dot"></span>').join('')}</div><div class="pin-pad">${[1,2,3,4,5,6,7,8,9,'',0,'⌫'].map(d=>d===''?'<span class="pin-key empty"></span>':`<button type="button" class="pin-key" data-act="pinDigit" data-value="${d}">${d}</button>`).join('')}</div>`}<button class="pin-back" data-act="backToProfiles">‹ Switch profile</button></div>`}
function updateDots(){qa('.pin-dot').forEach((d,i)=>d.classList.toggle('filled',i<pin.buf.length))}
async function digit(d){if(!pin.id||pin.busy||pin.mode==='claim')return;if(d==='⌫')pin.buf=pin.buf.slice(0,-1);else if(/^\d$/.test(d)&&pin.buf.length<4)pin.buf+=d;updateDots();if(pin.buf.length!==4)return;pin.busy=true;await new Promise(r=>setTimeout(r,200));const buf=pin.buf;try{if(pin.mode==='create'){pin.first=buf;pin.mode='confirm';pin.buf='';pin.busy=false;renderPin();return}if(pin.mode==='confirm'){if(buf!==pin.first){pin.mode='create';pin.first='';throw Error('PINs did not match. Try again.')}await api('/api/claim','POST',{profileId:pin.id,claimCode:pin.claimCode,pin:buf});await signedIn();return}await api('/api/login','POST',{profileId:pin.id,pin:buf});await signedIn()}catch(err){q('#pinDots')?.classList.add('shake');toast(err.message);await new Promise(r=>setTimeout(r,350));pin.buf='';pin.busy=false;updateDots();if(pin.mode==='create'&&!pin.first)renderPin()}}
async function signedIn(){const p=B.profiles.find(x=>x.id===pin.id);entry.innerHTML=`<div class="pin-card" style="animation:zoom .48s var(--ease)"><div style="border:3px solid var(--red);padding:10px;border-radius:50%;box-shadow:0 0 55px rgba(235,105,117,.23)">${avatar(p,'xxl')}</div><div class="entry-title" style="font-size:30px">You're in.</div><div class="entry-sub">Welcome to gymclo, ${esc(p.name)}.</div></div>`;pin={id:'',mode:'enter',buf:'',first:'',busy:false};await new Promise(r=>setTimeout(r,820));tab='home';await refresh()}
async function imageFile(file,max=700,q=.74){if(!file)return '';if(!file.type.startsWith('image/'))throw Error('Please select an image');const blob=URL.createObjectURL(file);try{const im=new Image();im.src=blob;try{await im.decode()}catch{throw Error('This photo format cannot be opened. Try JPG, PNG or WebP (convert HEIC to JPG if necessary).')}const scale=Math.min(1,max/Math.max(im.width,im.height));const can=document.createElement('canvas');can.width=Math.max(1,Math.floor(im.width*scale));can.height=Math.max(1,Math.floor(im.height*scale));can.getContext('2d').drawImage(im,0,0,can.width,can.height);const out=can.toDataURL('image/jpeg',q);if(out.length>600000)throw Error('Image too large. Try a smaller one.');return out}finally{URL.revokeObjectURL(blob)}}
function openModal(content){modal.hidden=false;modal.innerHTML=`<div class="modal-dialog" role="dialog" aria-modal="true"><div class="modal-title-row"><h2 class="modal-title">${content.title}</h2><button class="modal-close" type="button" data-act="closeModal" aria-label="Close">×</button></div>${content.body}</div>`}
function closeModal(){modal.hidden=true;modal.innerHTML=''}
function modalWallpaper(){const t=setWallpaper();openModal({title:'Make gymclo yours',body:`<p class="section-desc">Wallpaper choices belong to your profile and sync across devices. They do not change anyone else's wallpaper.</p><div class="label">Choose an atmosphere</div><div class="wall-presets">${['ember','oxide','slate','noir'].map(x=>`<button class="wall-option ${x} ${!t.photo&&t.theme===x?'active':''}" data-act="wallChoice" data-value="${x}" aria-label="${x} wallpaper"></button>`).join('')}</div><label class="field">Upload your own wallpaper</label><input class="input" id="wallInput" type="file" accept="image/*"><label class="field">Wallpaper darkness</label><input class="input" type="range" id="wallDim" min="0" max="0.7" step="0.05" value="${t.dim}"><label class="field">Text colour presets</label><div class="colour-presets">${[['default','Classic'],['rose','Rose'],['ice','Ice'],['mint','Mint'],['gold','Gold'],['lavender','Lavender'],['warm','Warm']].map(([id,label])=>`<button type="button" class="colour-swatch ${t.textColor===id?'active':''}" data-act="textTheme" data-value="${id}">${label}</button>`).join('')}</div><div class="button-row"><button class="btn ghost" data-act="wallReset">Restore default</button><button class="btn" data-act="closeModal">Done</button></div>`})}
function modalMember(id){const p=profile(id)||{},isCreate=!id;openModal({title:isCreate?'Add a crew member':'Edit profile',body:`<form data-form="${isCreate?'addMember':'editMember'}" data-id="${esc(id||'')}"><div style="display:flex;gap:14px;align-items:center">${avatar(p,'lg')}<div class="grow"><label class="field" style="margin-top:0">Display name</label><input class="input" name="name" maxlength="28" value="${esc(p.name||'')}" required placeholder="Name"></div></div><label class="field">Profile picture</label><input class="input" type="file" name="avatar" accept="image/*"><div class="support-note" style="margin-top:8px">${isCreate?'After creating the member you will receive a private claim code to share with them. They choose their own four-digit PIN.':'The picture can be changed without affecting attendance or votes.'}</div><button class="btn full" style="margin-top:16px">${isCreate?'Add profile':'Save profile'}</button></form>${!isCreate&&p.id===me().id?`<button class="btn ghost full" style="margin-top:10px" data-act="logout">${I('logout',15)} Switch profile / sign out</button>`:''}`})}
function invitation(code){openModal({title:'Invitation created',body:`<p class="section-desc">Send this code privately to the member. It is shown only now; you can generate a new one in Admin.</p><div class="card soft" style="text-align:center;font-size:21px;font-weight:850;letter-spacing:.11em;overflow-wrap:anywhere" id="inviteCode">${esc(code)}</div><button class="btn full" data-act="copyInvite" data-value="${esc(code)}" style="margin-top:15px">Copy invitation code</button>`})}
function modalProposal(){const start=addDays(cycleStart(today()),28);openModal({title:'Pitch four fitness forfeits',body:`<p class="section-desc">Four progressively harder challenges for ${fmt(start)} – ${fmt(addDays(start,27))}. Members vote on the next cycle.</p><form data-form="proposal"><label class="field">Proposal name</label><input class="input" name="title" maxlength="64" required placeholder="The endurance ladder">${fallback.slice(0,4).map((f,i)=>`<label class="field">Week ${i+1} · ${i===0?'entry level':i===3?'hardest':'build up'}</label><input class="input" name="f${i}" maxlength="180" required value="${esc(f)}">`).join('')}<button class="btn full" style="margin-top:17px">Submit for group vote</button></form>`})}

async function showProof(id){const result=await api(`/api/checkins/${id}/proof`);openModal({title:'Workout evidence',body:result.proof?`<img src="${esc(result.proof)}" alt="Submitted workout evidence" style="width:100%;max-height:65vh;object-fit:contain;border-radius:14px">`:'<p class="muted">No preview photo for this demo entry.</p>'})}
function celebrate(count,n){if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){toast('Workout logged!');return}const C=489,offset=C*(1-Math.min(1,count/n));cel.hidden=false;cel.innerHTML=`<div class="celebrate-content"><div class="eyebrow">ANOTHER ONE IN THE BOOKS</div><div class="celebrate-ring"><svg viewBox="0 0 200 200"><circle class="track" cx="100" cy="100" r="78"/><circle class="active" cx="100" cy="100" r="78" style="--offset:${offset}"/></svg><div class="celebrate-count num"><span id="animateCount">0</span>/${n}</div></div><div class="celebrate-heading">${count>=n?'Week conquered.':'Session secured.'}</div><div class="celebrate-copy">${count>=n?'You hit your weekly standard.':`${n-count} to go. Keep showing up.`}</div><svg class="trail" viewBox="0 0 240 52" aria-hidden="true"><path class="trail-path" d="M5 41 C40 41 42 12 76 29 S130 54 153 18 S200 14 235 3"/><circle cx="235" cy="3" r="4" fill="var(--red-light)"/></svg><button class="btn ghost small" data-act="closeCelebration" style="margin-top:17px">Back to dashboard</button></div>`;for(let i=0;i<24;i++){const a=i/24*Math.PI*2,dist=100+Math.random()*170,e=document.createElement('span');e.className='particle';e.style.setProperty('--dx',`${Math.cos(a)*dist}px`);e.style.setProperty('--dy',`${Math.sin(a)*dist}px`);e.style.setProperty('--r',`${Math.round(Math.random()*520)}deg`);e.style.setProperty('--delay',`${Math.random()*.23}s`);cel.append(e)}const counter=q('#animateCount'),start=performance.now();const anim=t=>{const p=Math.min(1,(t-start)/950);counter.textContent=Math.round(count*(1-Math.pow(1-p,3)));if(p<1&&counter.isConnected)requestAnimationFrame(anim)};requestAnimationFrame(anim);clearTimeout(celebrate.timer);celebrate.timer=setTimeout(()=>cel.hidden=true,2800)}
async function act(a,btn){const value=btn.dataset.value,id=btn.dataset.id;switch(a){case'clearProof':formPhoto='';{const box=q('#proofPreview');if(box){box.classList.remove('has-image');box.innerHTML=''}const name=q('#proofUploadTitle');if(name)name.textContent='Attach workout evidence';const file=q('#checkinPhoto');if(file)file.value=''}break;case'textTheme':await saveWallpaper({textColor:value});modalWallpaper();toast('Text colour updated');break;case'editChat':chatModal('',id);break;case'replyChat':chatModal(id);break;case'chatReact':await api(`/api/messages/${id}/react`,'POST',{emoji:value});await refresh();break;case'gifSelect':{const inp=q('#gifInput');if(inp)inp.value=`https://giphy.com/embed/${value}`;toast('GIF selected');break}case'gifSearch':{const search=q('#gifSearch')?.value?.trim();if(!search)throw Error('Enter a GIF search term');const result=await api('/api/giphy/search?q='+encodeURIComponent(search));const holder=q('#gifResults');if(holder)holder.innerHTML=result.gifs.map(g=>`<button type="button" data-act="gifSelect" data-value="${esc(g.id)}"><img src="${esc(g.url)}" alt="Choose GIF"></button>`).join('')||'<p class="micro">No GIFs found.</p>';break}case'nav':tab=value;window.scrollTo({top:0,behavior:'smooth'});render();break;case'wallpaper':modalWallpaper();break;case'vinylToggle':toggleVinyl();break;case'deleteSession':if(!me()?.isAdmin)throw Error('Admin only');if(!confirm('Remove this approved workout? Only this session will be removed; the date still counts if other sessions remain.'))return;await api(`/api/admin/checkins/${id}/delete`,'POST');await refresh();toast('Approved workout removed');break;case'wallChoice':await saveWallpaper({theme:value,photo:''});qa('.wall-option').forEach(b=>b.classList.toggle('active',b.dataset.value===value));break;case'wallReset':await saveWallpaper({theme:'ember',photo:'',dim:.18});modalWallpaper();break;case'closeModal':closeModal();break;case'closeCelebration':cel.hidden=true;break;case'kind':selectedWorkout=value;qa('.kind-chip').forEach(b=>b.classList.toggle('active',b.dataset.value===value));break;case'admin':if(!me()?.isAdmin){toast('Admin only');break}if(!demoMode){let lock;try{lock=await api('/api/admin/status')}catch(err){throw Error('Server update required: upload the matching server.js to GitHub. '+err.message)}if(!lock.unlocked){openModal({title:'Unlock admin',body:'<p class="section-desc">Enter the admin PIN to edit forfeits and manage members.</p><form data-form="unlockAdmin"><label class="field">Four-digit admin PIN</label><input class="input" name="pin" inputmode="numeric" type="password" pattern="[0-9]{4}" minlength="4" maxlength="4" autocomplete="off" required><button class="btn full" style="margin-top:15px">Unlock control room</button></form>'});break}}tab='admin';render();break;case'cycle':forfeitView=value;render();break;case'profile':modalMember(me().id);break;case'chooseProfile':chooseProfile(id,btn.dataset.index);break;case'backToProfiles':pin={id:'',mode:'enter',buf:'',first:'',busy:false};renderEntry();break;case'pinDigit':await digit(value);break;case'logout':await api('/api/logout','POST');S=null;B=await api('/api/bootstrap');closeModal();renderEntry();break;case'cal':{let m=calendarMonth||activeMonth(),[y,mo]=m.split('-').map(Number);const d=new Date(Date.UTC(y,mo-1+Number(value),1));calendarMonth=`${d.getUTCFullYear()}-${n2(d.getUTCMonth()+1)}`;if(calendarMonth>activeMonth())calendarMonth=activeMonth();render();break}case'forfeitMonth':forfeitView=value;render();break;case'proof':await showProof(id);break;case'review':await api(`/api/checkins/${id}/review`,'POST',{status:value});await refresh();toast(`Submission ${value}`);break;case'markForfeit':await api('/api/forfeit-completed','POST',{profileId:id,week:value});await refresh();toast('Forfeit marked as completed');break;case'copyLink':await navigator.clipboard.writeText(location.origin);toast('Website link copied. Send each friend their separate invitation code.');break;case'copySummary':await navigator.clipboard.writeText(q('#summaryText').value);toast('Copied for WhatsApp');break;case'shareSummary':{const text=q('#summaryText').value;const shareUrl='https://wa.me/?text='+encodeURIComponent(text);window.open(shareUrl,'_blank','noopener');break}case'addMember':modalMember();break;case'editMember':modalMember(id);break;case'copyInvite':await navigator.clipboard.writeText(value);toast('Invitation code copied');break;case'resetPin':if(!confirm('Reset this member’s PIN? Their existing login sessions will be signed out.'))return;{const response=await api(`/api/profiles/${id}/reset`,'POST');await refresh();invitation(response.inviteCode);break}case'finalizeMvp':if(!confirm('Finalize the previous cycle’s votes and award the Diamond Crown to the unique winner?'))return;await api('/api/admin/mvp/finalize','POST',{start:value});await refresh();toast('Diamond Crown awarded to the voted MVP');break;case'propose':modalProposal();break;case'proposalVote':await api('/api/proposal-votes','POST',{proposalId:id});await refresh();toast('Your vote is recorded');break;case'applyProposal':if(!confirm('Apply these four forfeits to the next challenge cycle?'))return;await api('/api/apply-proposal','POST',{proposalId:id});await refresh();toast('Next cycle’s four forfeits updated');break;case'react':await api(`/api/feed/${id}/react`,'POST',{emoji:value});await refresh();break;case'shareSession':{const c=S.checkins.find(x=>x.id===id);if(!c||c.profileId!==me().id)throw Error('Not your session');await api(`/api/checkins/${id}/visibility`,'POST',{visible:!c.shareToFeed});await refresh();toast(c.shareToFeed?'Post made private':'Your post will appear once approved');break}case'mvp':if(!confirm('Cast your one MVP vote for this member?'))return;await api('/api/mvp-votes','POST',{start:value,candidateId:id});await refresh();toast('MVP vote submitted');break;case'reload':await boot();break}}
document.addEventListener('click',async e=>{const btn=e.target.closest('[data-act]');if(!btn||btn.disabled)return;try{await act(btn.dataset.act,btn)}catch(err){toast(err.message)}});
document.addEventListener('keydown',e=>{if(entry.hidden||!pin.id||pin.mode==='claim')return;if(/^\d$/.test(e.key)){e.preventDefault();digit(e.key)}else if(e.key==='Backspace'){e.preventDefault();digit('⌫')}else if(e.key==='Escape'){pin.id='';renderEntry()}});
entry.addEventListener('keydown',e=>{if(pin.id)return;const tiles=qa('.profile-tile');if(!tiles.length)return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){selection=Math.max(0,Math.min(tiles.length-1,selection+(e.key==='ArrowRight'?1:-1)));qa('.profile-tile').forEach((t,i)=>t.classList.toggle('active',i===selection));tiles[selection].scrollIntoView({block:'nearest',inline:'center',behavior:'smooth'});e.preventDefault()}if(e.key==='Enter'&&e.target.closest('.profile-gallery')===null){tiles[selection]?.click()}});
entry.addEventListener('mouseover',e=>{const t=e.target.closest('.profile-tile');if(t){qa('.profile-tile').forEach(b=>b.classList.toggle('active',b===t))}});
modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});
document.addEventListener('input',e=>{if(e.target.id==='wallDim')document.documentElement.style.setProperty('--shade',+e.target.value)});
document.addEventListener('change',async e=>{if(e.target.id==='wallInput'&&e.target.files[0]){try{const photo=await imageFile(e.target.files[0],1100,.7);await saveWallpaper({photo});toast('Wallpaper saved to your profile')}catch(err){toast(err.message)}}if(e.target.id==='checkinPhoto'&&e.target.files[0]){try{formPhoto=await imageFile(e.target.files[0],750,.62);const label=q('#proofUploadTitle');if(label)label.textContent='Evidence ready';const preview=q('#proofPreview');if(preview){preview.classList.add('has-image');preview.innerHTML=`<img alt="Selected workout evidence" src="${formPhoto}"><span class="grow micro">Photo attached · ready to submit</span><button type="button" class="proof-remove" data-act="clearProof">Remove</button>`}toast('Evidence ready to submit')}catch(err){formPhoto='';toast(err.message)}}if(e.target.id==='wallDim'){try{await saveWallpaper({dim:+e.target.value});toast('Wallpaper darkness saved')}catch(err){toast(err.message)}}if(e.target.dataset.archive==='calendar'){calendarMonth=e.target.value;render()}if(e.target.dataset.archive==='adminCycle'){adminCycle=e.target.value;render()}if(e.target.dataset.archive==='approvedMonth'){approvedMonth=e.target.value;render()}if(e.target.name==='month'&&e.target.closest('[data-form="rules"]')){adminMonth=e.target.value;render()}});
document.addEventListener('submit',async e=>{const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();if(loading)return;loading=true;const submit=q('button[type=submit]',form);if(submit)submit.disabled=true;const b=Object.fromEntries(new FormData(form));try{switch(form.dataset.form){case'chatPost':case'chatEdit':{const file=form.querySelector('[name=image]')?.files?.[0],photo=file?await imageFile(file,850,.67):undefined;const isEdit=form.dataset.form==='chatEdit',body={text:b.text||'',gifUrl:b.gifUrl||''};if(isEdit){if(photo!==undefined)body.image=photo;else if(b.removeImage==='on')body.image='';await api('/api/messages/'+form.dataset.id,'PATCH',body)}else{body.parentId=form.dataset.parent||null;body.image=photo||'';await api('/api/messages','POST',body)}closeModal();await refresh();toast(isEdit?'Message updated':'Message posted');break}case'jukebox':{if(!validSoundcloudUrl(b.url))throw Error('Paste a public soundcloud.com track or playlist link');let trackTitle='';try{const info=await fetch('https://soundcloud.com/oembed?format=json&url='+encodeURIComponent(b.url)).then(r=>r.ok?r.json():null);trackTitle=String(info?.title||'').slice(0,120)}catch{/* A valid SoundCloud widget URL can still be saved if oEmbed is unavailable */}const saved=await api('/api/jukebox','POST',{url:b.url,title:trackTitle});S.jukebox=saved.jukebox;render();toast('Crew soundtrack updated. Tap the vinyl to play.');break}case'setup':await api('/api/setup','POST',{name:b.name,setupCode:b.setupCode,pin:b.pin});await boot();break;case'claimCode':pin.claimCode=b.code.trim().toUpperCase();pin.mode='create';pin.buf='';renderPin();break;case'checkin':if(!formPhoto)throw Error('Choose a proof photo before submitting');await api('/api/checkins','POST',{kind:selectedWorkout,note:b.workoutNote||q('#workoutNote')?.value||'',proof:formPhoto,shareToFeed:b.shareToFeed==='on'});formPhoto='';{const hadToday=todayLogged();await refresh();const count=weekCount(me().id,activeWeek());if(hadToday)toast('Extra workout saved — this day still counts as 1 toward your weekly goal');else celebrate(count,target());}break;case'addMember':{const avatarFile=form.querySelector('[name=avatar]').files[0],avatar=avatarFile?await imageFile(avatarFile,400,.7):'';const result=await api('/api/profiles','POST',{name:b.name,avatar});await refresh();invitation(result.inviteCode);break}case'editMember':{const avatarFile=form.querySelector('[name=avatar]').files[0],p=profile(form.dataset.id);await api(`/api/profiles/${form.dataset.id}`,'PATCH',{name:b.name,avatar:avatarFile?await imageFile(avatarFile,400,.7):p.avatar});await refresh();closeModal();toast('Profile updated');break}case'unlockAdmin':await api('/api/admin/unlock','POST',{pin:b.pin});closeModal();tab='admin';render();toast('Admin unlocked for 15 minutes');break;case'adminCheckin':await api('/api/admin/checkins','POST',{profileId:b.profileId,day:b.day,kind:b.kind,note:b.note||''});await refresh();toast('Missed session added to attendance');break;case'setMvpCrown':{if(!confirm('Award the Diamond Crown to this member? The previous MVP will lose the crown.'))break;await api('/api/admin/mvp/crown','POST',{profileId:b.profileId});await refresh();toast('Diamond Crown awarded');break;}case'cycleRules':await api('/api/cycle-rules','POST',{start:b.start,target:+b.target,forfeits:Array.from({length:4},(_,i)=>b['f'+i])});await refresh();toast('Four-week forfeits updated');break;case'rules':await api('/api/rules','POST',{month:b.month,target:+b.target,forfeits:Array.from({length:5},(_,i)=>b['f'+i])});await refresh();toast('Monthly rules saved');break;case'proposal':await api('/api/proposals','POST',{start:addDays(cycleStart(today()),28),title:b.title,forfeits:Array.from({length:4},(_,i)=>b['f'+i])});await refresh();closeModal();toast('Four-week proposal published for voting');break}}catch(err){toast(err.message)}finally{loading=false;if(submit?.isConnected)submit.disabled=false}});
boot();

